 *
 * Original C:
 *   for i:
 *     x[i] = 0;
 *     y[i] = 0;
 *     b[i] = (i+1)/fn/2.0 + 4;
 *
 *   A initial lower-triangular construction, then:
 *     B = A * A^T;
 *     A = B;
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    // Tunable constants for 1D/vector schedules and SPD kernel.
    const int INIT_VEC_WIDTH = 8;   // for x, y, b initialization
    const int INIT_TILE_SIZE = 64;  // tile for parallel 1D init
    const int SPD_VEC_WIDTH  = 8;   // for SPD matrix multiply

    Var i("i"), col("col"), row("row");
    Var io("io"), ii("ii");

    // --------------------------------------------
    // 1D initialization for x, y, b
    // --------------------------------------------
    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    // We'll keep n as Expr and cast where needed.
    Expr n_expr_i = Expr(n);                // int-valued Expr
    Expr n_expr   = cast<num_t>(n_expr_i);  // DATA_TYPE-valued Expr

    // x[i] = 0; y[i] = 0;
    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    // b[i] = (i+1)/n/2.0 + 4;
    // Carefully keep arithmetic order to preserve original semantics.
    Expr term1 = cast<num_t>(i + 1) / n_expr;                   // (i+1)/n
    Expr term2 = term1 / cast<num_t>(Expr(2.0));               // ((i+1)/n)/2
    Expr term3 = term2 + cast<num_t>(Expr(4.0));               // ... + 4
    init_b(i)  = term3;

    // Schedule: 1D ops are cheap relative to O(n^3) work, but we still
    // vectorize and parallelize to improve throughput for large n.
    init_x.compute_root()
          .split(i, io, ii, INIT_TILE_SIZE)
          .parallel(io)
          .vectorize(ii, INIT_VEC_WIDTH);

    init_y.compute_root()
          .split(i, io, ii, INIT_TILE_SIZE)
          .parallel(io)
          .vectorize(ii, INIT_VEC_WIDTH);

    init_b.compute_root()
          .split(i, io, ii, INIT_TILE_SIZE)
          .parallel(io)
          .vectorize(ii, INIT_VEC_WIDTH);

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // --------------------------------------------
    // Lower-triangular A initialization (A_init)
    // --------------------------------------------
    //
    // A[i][j] = (-j % n) / n + 1 for j <= i, 0 otherwise,
    // with main diagonal forced to 1.
    //
    // We store A(row=i, col=j) at A(j, i), i.e., first dimension is
    // column, second dimension is row.
    Func A_init("A_init");

    // (-j % n) / n + 1  -> implement as - (j % n) / n + 1
    Expr neg_mod = -(col % n);
    Expr base    = cast<num_t>(neg_mod) / n_expr + cast<num_t>(Expr(1.0));

    // col = j, row = i
    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),  // diagonal = 1
               select(col <= row,
                      base,             // strict lower triangle (and diagonal before override)
                      cast<num_t>(Expr(0.0)))); // strict upper triangle = 0

    // We materialize A_init once (compute_root) so that the SPD
    // computation can re-use its values without recomputing the
    // (-j % n)/n + 1 expression O(n^3) times.
    A_init.compute_root()
          .parallel(row)
          .vectorize(col, SPD_VEC_WIDTH);

    // --------------------------------------------
    // Make A symmetric positive definite:
    // B = A * A^T; then A = B.
    // --------------------------------------------
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    //
    // In our layout: A(r, t) is A[row=r, col=t] stored as A(t, r).
    // So:
    //   A_init(t, row) = A[row, t]
    //   A_init(t, col) = A[col, t]
    // B(row=r, col=s) = sum_t A[row, t] * A[s, t]
    //                 = sum_t A_init(t, row) * A_init(t, col)
    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    // Pure definition: initialize to 0
    SPD(col, row) = cast<num_t>(Expr(0.0));
    // Update: accumulate dot product over t_dom
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // Schedule for SPD = A_init * A_init^T:
    //
    // - compute_root(): materialize entire SPD result once into A
    // - parallel over rows (second dimension) to utilize many cores
    // - vectorize across columns (first dimension) for SIMD
    SPD.compute_root()
       .parallel(row)
       .vectorize(col, SPD_VEC_WIDTH);

    // The update definition (the reduction) needs its own schedule;
    // we apply the same parallel/vector pattern to its loops.
    SPD.update()
       .parallel(row)
       .vectorize(col, SPD_VEC_WIDTH);

    // Realize SPD into A buffer (shape n x n).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

    // Initialize data
    init_array(n, A, b, x, y);

    // Set up Halide parameters and ImageParams for the kernel.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam y_param(type_of<num_t>(), 1, "y_param");

    Param<int> pi("pi");  // current i
    Param<int> pj("pj");  // current j
    Param<int> pn("pn");  // n (for convenience in ranges)

    A_param.set(A);
    b_param.set(b);
    x_param.set(x);
    y_param.set(y);
    pn.set(n);

    // --------------------------------------------------------------------
    // Halide helpers for the LU decomposition and forward/back substitution
    //
    // We follow the same scalar formulas as in the original reference
    // code, but:
    //   - Each scalar update is implemented as a tiny Halide pipeline
    //     (0-D Func) using an RDom to express the inner dot product.
    //   - We explicitly vectorize the reduction dimension to use SIMD
    //     for each dot product.
    // --------------------------------------------------------------------

    const int DOT_VEC_WIDTH = 8;  // vector width for inner products

    // 1) L-part update:
    // For j < i:
    //   w = A[i][j];
    //   for k = 0..j-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w / A[j][j];
    //
    // In our layout: A[i][j] == A_param(j, i).
    // We compute the new scalar A[i][j] as:
    //   A_param(pj, pi) - sum_{k=0..pj-1} A_param(k, pi) * A_param(pj, k)
    // then divide by A_param(pj, pj).
    RDom rL(0, pj, "rL");
    Func update_L("update_L");
    {
        Expr sum_L = sum(A_param(rL, pi) * A_param(pj, rL));
        update_L() = (A_param(pj, pi) - sum_L) / A_param(pj, pj);
    }

    // 2) U-part update:
    // For j >= i:
    //   w = A[i][j];
    //   for k = 0..i-1: w -= A[i][k] * A[k][j];
    //   A[i][j] = w;
    //
    // In our layout: A[i][j] == A_param(j, i).
    // new A[i][j] = A_param(j, i) - sum_{k=0..i-1} A_param(k, i) * A_param(j, k).
    RDom rU(0, pi, "rU");
    Func update_U("update_U");
    {
        Expr sum_U = sum(A_param(rU, pi) * A_param(pj, rU));
        update_U() = A_param(pj, pi) - sum_U;
    }

    // 3) Forward substitution for y:
    // For i = 0..n-1:
    //   w = b[i];
    //   for j = 0..i-1: w -= A[i][j] * y[j];
    //   y[i] = w;
    //
    // y[i] = b[i] - sum_{j=0..i-1} A[i][j] * y[j].
    // In our layout: A[i][j] == A_param(j, i).
    RDom rY(0, pi, "rY");
    Func compute_y("compute_y");
    {
        Expr sum_Y = sum(A_param(rY, pi) * y_param(rY));
        compute_y() = b_param(pi) - sum_Y;
    }

    // 4) Back substitution for x:
    // For i = n-1..0:
    //   w = y[i];
    //   for j = i+1..n-1: w -= A[i][j] * x[j];
    //   x[i] = w / A[i][i];
    //
    // x[i] = (y[i] - sum_{j=i+1..n-1} A[i][j] * x[j]) / A[i][i].
    // In our layout: A[i][j] == A_param(j, i).
    //
    // Domain j = i+1 .. n-1  -> RDom(pi+1, n-(pi+1))
    RDom rX(pi + 1, pn - (pi + 1), "rX");
    Func compute_x("compute_x");
    {
        Expr sum_X = sum(A_param(rX, pi) * x_param(rX));
        compute_x() = (y_param(pi) - sum_X) / A_param(pi, pi);
    }

    // ----------------------------------------
    // Schedule the small helper pipelines
    // ----------------------------------------
    //
    // Each helper is 0-dimensional (a scalar), but its update
    // definition performs a 1D reduction over an RDom. We
    // vectorize that inner reduction to exploit SIMD for each
    // dot product.
    update_L.compute_root();
    update_L.update().vectorize(rL.x, DOT_VEC_WIDTH);

    update_U.compute_root();
    update_U.update().vectorize(rU.x, DOT_VEC_WIDTH);

    compute_y.compute_root();
    compute_y.update().vectorize(rY.x, DOT_VEC_WIDTH);

    compute_x.compute_root();
    compute_x.update().vectorize(rX.x, DOT_VEC_WIDTH);

    // Compile the small helper pipelines once.
    update_L.compile_jit();
    update_U.compile_jit();
    compute_y.compile_jit();
    compute_x.compile_jit();

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // LU decomposition
    for (int i = 0; i < n; i++) {
        pi.set(i);  // set once per row

        // L-part: j < i
        for (int j = 0; j < i; j++) {
            pj.set(j);
            Halide::Buffer<num_t> tmp = update_L.realize();
            // A[i][j] -> A(j, i)
            A(j, i) = tmp();
        }

        // U-part: j >= i
        for (int j = i; j < n; j++) {
            pj.set(j);
            Halide::Buffer<num_t> tmp = update_U.realize();
            A(j, i) = tmp();
        }
    }

    // Forward substitution to compute y
    for (int i = 0; i < n; i++) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_y.realize();
        y(i) = tmp();
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        Halide::Buffer<num_t> tmp = compute_x.realize();
        x(i) = tmp();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result vector x, similar to print_array().
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            if (i % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << x(i) << ' ';
        }
        std::cerr << '\n';
    }

    // Print timing (seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
