static void init_array(int n,
                       Halide::Buffer<num_t, 2> &A,   // shape (n, n): (x=col, y=row)
                       Halide::Buffer<num_t, 1> &b,   // shape (n)
                       Halide::Buffer<num_t, 1> &x,   // shape (n)
                       Halide::Buffer<num_t, 1> &y) { // shape (n)
    Var i("i"), col("col"), row("row");

