    // schedule simple; the cost of this step is negligible compared
    // to the n^3 SPD construction.

    Func init_x("init_x"), init_y("init_y"), init_b("init_b");

    Expr n_expr = Expr(n);
    Expr n_num = cast<num_t>(n_expr);

    init_x(i) = cast<num_t>(Expr(0.0));
    init_y(i) = cast<num_t>(Expr(0.0));

    // term = (i+1)/n/2 + 4
    // We keep the algebra as in the C reference for bit‑for‑bit behavior.
    Expr term1 = cast<num_t>(i + 1) / n_num;
    Expr term2 = term1 / cast<num_t>(Expr(2.0));
    Expr term3 = term2 + cast<num_t>(Expr(4.0));
    init_b(i) = term3;

    // Default schedule is fine here (O(n)), so just compute at root.
    init_x.compute_root();
    init_y.compute_root();
    init_b.compute_root();

    init_x.realize(x);
    init_y.realize(y);
    init_b.realize(b);

    // -----------------------------------------
    // 2) Initial lower-triangular A_init
    // -----------------------------------------
    //
    // A[i][j] = (-j % n) / n + 1 for j <= i, 0 otherwise, and A[i][i] = 1.
    //
    // Stored as A(col=j, row=i) in the Buffer: A(j, i).
    //
    // We construct A_init as a separate Func and then form
    // A := A_init * A_init^T to obtain a symmetric positive
    // semi-definite matrix. We heavily schedule the SPD step, which
    // is O(n^3) and dominates initialization time.

    Func A_init("A_init");

    // (-j % n) / n + 1  -> implement as - (j % n) / n + 1
    Expr neg_mod = -(col % n);
    Expr base = cast<num_t>(neg_mod) / n_num + cast<num_t>(Expr(1.0));

    A_init(col, row) =
        select(col == row,
               cast<num_t>(Expr(1.0)),                 // diagonal = 1
               select(col <= row,
                      base,                            // lower triangle
                      cast<num_t>(Expr(0.0))));        // upper triangle = 0

    // -----------------------------------------
    // 3) SPD = A_init * A_init^T
    // -----------------------------------------
    //
    // B[r][s] = sum_t A[r][t] * A[s][t]
    //
    // With our layout A(row=i,col=j) stored at A(j,i):
    //   A(r, t) -> A_init(t, r)
    //   A(s, t) -> A_init(t, s)
    //
    // So we define:
    //   SPD(row=r, col=s) = sum_t A_init(t, r) * A_init(t, s)
    // and then realize SPD directly into A.

    Func SPD("SPD");
    RDom t_dom(0, n, "t_dom");

    SPD(col, row) = cast<num_t>(Expr(0.0));
    SPD(col, row) += A_init(t_dom, row) * A_init(t_dom, col);

    // -----------------------------------------
    // 4) Scheduling for A_init and SPD
    // -----------------------------------------
    //
    // A_init is cheap but reused heavily in SPD, so we compute it
    // once at root. SPD is a dense matrix multiply; we:
    //   - parallelize across rows (y dimension)
    //   - vectorize across columns (x dimension)
    //   - reorder the reduction so that the reduction variable is
    //     innermost, keeping vector loads of A_init contiguous.

    A_init.compute_root()
          .parallel(row)
          .vectorize(col, vec_width);

    SPD.compute_root()
       .parallel(row)
       .vectorize(col, vec_width);

    // For the update step, ensure the reduction variable is innermost
    // and keep the same row/col order. Vectorizing across 'col'
    // yields tight SIMD dot-products.
    SPD.update()
       .reorder(t_dom, col, row)
       .vectorize(col, vec_width)
       .parallel(row);

    // Realize SPD into the user-provided A buffer (n x n).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers:
    // A: 2D (n x n), first dimension = column (j), second = row (i)
    // b, x, y: 1D (n)
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 1> b(n), x(n), y(n);

