    Func compute_x("compute_x");
    {
        // Domain j = i+1 .. n-1  -> RDom(pi+1, n-(pi+1))
        RDom rX(pi + 1, pn - (pi + 1), "rX");
        Expr sum_X = sum(A_param(rX, pi) * x_param(rX));
        compute_x() = (y_param(pi) - sum_X) / A_param(pi, pi);
    }

    // Compile the small helper pipelines once for the host target.
    update_L.compile_jit(host_target);
    update_U.compile_jit(host_target);
    compute_y.compile_jit(host_target);
    compute_x.compile_jit(host_target);

    // Reuse a single scalar Buffer for all 0-D realizations to avoid
    // repeated tiny heap allocations and improve cache behavior.
    //
    // Using a 0-D Halide::Buffer here is equivalent to returning a
    // scalar, but lets us keep everything inside the Halide runtime.
    Halide::Buffer<num_t> scalar_buf = Halide::Buffer<num_t>::make_scalar();

    // ------------------------------------
    // Run the kernel and measure its time.
    // ------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // LU decomposition
    for (int i = 0; i < n; i++) {
        // L-part: j < i
