    for (int i = 0; i < n; i++) {
        pi.set(i);
        compute_y.realize(scalar_buf);
        y(i) = scalar_buf();
    }

    // Back substitution to compute x
    for (int i = n - 1; i >= 0; i--) {
        pi.set(i);
        compute_x.realize(scalar_buf);
        x(i) = scalar_buf();
